"""A PE and the XEX2 around it, written: the inverse of what `container` reads.

Measured against `xwifi.xex` as the console's own filesystem holds it -- a plugin that
loads -- and the shape below is that plugin's:

    headers end at 0x1000, the security structure at 0x120, nine optional headers:
    FILE_FORMAT_INFO, ORIGINAL_BASE, ENTRY_POINT, IMAGE_BASE, IMPORT_LIBRARIES,
    CHECKSUM_TIMESTAMP, ORIGINAL_PE_NAME, STATIC_LIBRARIES, EXECUTION_INFO
    FILE_FORMAT_INFO: not encrypted, compression 1 (basic), one block of 0x8000
    info_size 0x174, image flags 0x10000000, region and media 0xFFFFFFFF
    three page descriptors: one header page, one of code, six of data

**Not encrypted and not compressed in any way that needs a compressor**: compression 1
is a list of (bytes of data, bytes of zero fill) and the image is stored as it is, which
is what that plugin does and the least there is to get wrong when the failure is a
console that will not boot. Encryption is optional and the console does not require it.

Four things the console does check, each of which this answers for, and `container`'s
own `verify` reads all of them back:

* the header hash, which covers the headers outside ImageInfo and then everything up to
  the hash's own field -- so there is no fixpoint and it is written last;
* the page descriptor chain and the ImageHash that closes it;
* the import digest chain;
* an image of at least 0x8000 bytes, which is why that plugin carries a `.pad` section:
  smaller is refused with nothing said, and the descriptors have to describe every page
  the loader will map, so padding the *image* without a section to cover it leaves pages
  the hashes do not reach.

File alignment equals section alignment on purpose: with the image stored as it is the
loader rebuilds it straight from the file, so a section at file offset 0x200 cannot land
at RVA 0x1000.

The kernel's import identity and the image flags are that plugin's. A NAND module's own
flags are not a model to copy: `xbdm.xex` carries 0x30000006 and a media mask of
0xFF001721, which is flash-only, and `nomni.xex` -- which does not verify at all -- is
not one either.
"""

import struct
import hashlib

PAGE = 0x1000
SMALLEST = 0x8000
DIGEST = 20
DESCRIPTOR = 24

# What a page of each kind is called in a descriptor's low nibble.
HEADERS, CODE, DATA = 3, 1, 2


class Section:
    """One PE section: its name, its bytes, where it maps and its characteristics."""

    def __init__(self, name: str, data: bytes, rva: int, flags: int):
        self.name, self.data, self.rva, self.flags = name, bytes(data), rva, flags

    @property
    def code(self) -> bool:
        return bool(self.flags & 0x20)

    @property
    def pages(self) -> int:
        return -(-len(self.data) // PAGE)

    @property
    def span(self) -> int:
        return self.pages * PAGE

    def __repr__(self) -> str:
        return "Section(%s, %#x at %#x)" % (self.name, len(self.data), self.rva)


def runs(sections: list) -> list:
    """The page descriptors a list of sections comes to: the header pages, then one run
    a section by its kind, with neighbours of one kind merged -- a real module carries
    three or four descriptors and never one a section -- and no run spanning a 64 KB
    boundary.

    That last is measured on the bench console, on four plugins alike but for this:
    images of 0xF000 and of exactly 0x10000 load with one run per kind, 0x11000 with
    its data run carried from 0x9000 over the boundary does not load at all -- no
    module, no marker, nothing said -- and the same 0x11000 image with that run broken
    at 0x10000 loads and reads its own data from both sides of the boundary. So it is
    the crossing and not the size: plugins far larger run on this console, Nova.xex at
    0xA5000 among them. `launch.xex` is built the same way -- the one module in the
    collections stored as these are, loaded where these load and larger than 64 KB,
    0x16000 at 0x91F00000 -- and its four descriptors, 4 headers, 12 code, 4 code, 2
    data, are what this comes to for its shape. Below 64 KB no run reaches a boundary
    and the descriptors are what they were.
    """
    ordered = sorted(sections, key=lambda one: one.rva)
    out = []
    if ordered and ordered[0].rva:
        out.append((ordered[0].rva // PAGE, HEADERS))
    for one in ordered:
        if one.pages:
            out.append((one.pages, CODE if one.code else DATA))
    merged = []
    for count, kind in out:
        if merged and merged[-1][1] == kind:
            merged[-1] = (merged[-1][0] + count, kind)
        else:
            merged.append((count, kind))
    step, at, split = 0x10000 // PAGE, 0, []
    for count, kind in merged:
        while count:
            piece = min(count, step - at % step)
            split.append((piece, kind))
            at, count = at + piece, count - piece
    return split


def page_chain(image: bytes, told: list, page: int) -> tuple:
    """The descriptors and the ImageHash, chained backwards as the console reads them:
    the last descriptor's digest is zero, each other covers the run after it together
    with that run's whole descriptor, and the ImageHash covers the first the same way.
    """
    out = [bytearray(struct.pack(">I", count << 4 | kind) + bytes(DIGEST))
           for count, kind in told]
    at, starts = 0, []
    for count, _ in told:
        starts.append((at, count))
        at += count
    for index in range(len(out) - 2, -1, -1):
        start, count = starts[index + 1]
        out[index][4:] = hashlib.sha1(
            image[start * page:(start + count) * page] + bytes(out[index + 1])).digest()
    start, count = starts[0]
    whole = hashlib.sha1(
        image[start * page:(start + count) * page] + bytes(out[0])).digest()
    return b"".join(bytes(one) for one in out), whole


def import_chain(records: list) -> tuple:
    """The library records with their digests filled in, and the digest the security
    structure carries: the same backwards shape, each record covering the next one
    without its own length word, and the last one zero."""
    out = [bytearray(one) for one in records]
    for index in range(len(out) - 1, -1, -1):
        following = bytes(out[index + 1])[4:] if index + 1 < len(out) else None
        out[index][4:4 + DIGEST] = hashlib.sha1(following).digest() if following \
            else bytes(DIGEST)
    return [bytes(one) for one in out], hashlib.sha1(bytes(out[0])[4:]).digest()


def header_hash(data: bytes, security: int, headers: int) -> bytes:
    """What the console hashes over the headers: everything past ImageInfo up to where
    the headers end, and then everything from the start up to the hash's own field. The
    field lives inside ImageInfo and the hash covers only what is outside it, so this
    can be written last rather than solved for."""
    info = struct.unpack_from(">I", data, security + 0x108)[0]
    return hashlib.sha1(bytes(data[security + 8 + info:headers])
                        + bytes(data[:security + 8])).digest()


def build_pe(sections: list, base: int, entry: int,
             directories: dict | None = None) -> bytes:
    """A PE32 the console's loader takes: the DOS stub, the COFF header, the optional
    header under subsystem 14, the section table, and each section's bytes at the
    offset the table gives -- which is its RVA, since the two alignments are equal."""
