    size = max(one.rva + one.span for one in ordered)
    head = struct.pack("<H", 0x010B) + b"\x08\x00"
    head += struct.pack("<3I", sum(len(one.data) for one in ordered if one.code), 0, 0)
    head += struct.pack("<3I", entry, ordered[0].rva, 0)
    head += struct.pack("<3I", base, PAGE, PAGE)
    head += struct.pack("<6H", 4, 0, 0, 0, 4, 0) + struct.pack("<I", 0)
    head += struct.pack("<3I", size, PAGE, 0)
