    # loads carries; nothing here depends on them.
    head += struct.pack("<2H", 14, 0) + struct.pack("<4I", 0x40000, 0x40000,
                                                    0x1000, 0x1000)
    head += struct.pack("<2I", 0, 16)
    for index in range(16):
        head += struct.pack("<2I", *told.get(index, (0, 0)))
