    table, body = b"", b""
    at = (len(before) + len(ordered) * 40 + PAGE - 1) & ~(PAGE - 1)
    for one in ordered:
        table += one.name.encode("latin-1").ljust(8, b"\0")
        table += struct.pack("<4I", len(one.data), one.rva, one.span, at)
        table += struct.pack("<3I", 0, 0, 0) + struct.pack("<I", one.flags)
        body += one.data.ljust(one.span, b"\0")
        at += one.span
